SELECT rentabilidad_1.poblacion_distribuidor_gvf_gvi AS poblacion_distribuidor_gvf_gvi,   ((CAST((CAST(SUM(rentabilidad_1.in) AS double precision) / NULLIF(SUM(rentabilidad_1.cf),0)) AS double precision) * CAST(cast('0.46999999999999997' as double precision) AS double precision)) - (CAST((SUM(rentabilidad_1.total_venta) + SUM(rentabilidad_1.total_reparto)) AS double precision) / NULLIF(SUM(rentabilidad_1.cf),0))) AS usr_calculation_2160818191446896_ok FROM rentabilidad_1 WHERE ((rentabilidad_1.sede_foraneo_sintec = 'Foraneo') AND (rentabilidad_1.zona = 'NR')) GROUP BY rentabilidad_1.poblacion_distribuidor_gvf_gvi;
